using System;using System.IO;using System.Text;using System.Collections;using System.Collections.Specialized;using System.Globalization;using System.Xml;using Nwc.XmlRpc;
static class Host {
 static string H(string s){if(s==null)return "-";if(s.Length==0)return ".";string o="";foreach(char c in s)o+=((int)c&255).ToString("x2")+((int)c>>8).ToString("x2");return o;}
 static string D(string h){if(h=="-")return null;if(h==".")return "";var b=Convert.FromHexString(h);string o="";for(int i=0;i<b.Length;i+=2)o+=(char)(b[i]|b[i+1]<<8);return o;}
 static string Error(Exception e)=>e.GetType().FullName+":"+H(e.Message);
 static object Atom(int kind,string p)=>kind switch{0=>null,1=>p,2=>int.Parse(p),3=>bool.Parse(p),4=>double.Parse(p,CultureInfo.InvariantCulture),5=>long.Parse(p),6=>new ArrayList{p,null,7,new byte[0]},7=>new OrderedDictionary{{"z",p},{"a",null},{"k",7}},8=>Convert.FromHexString(p),9=>new DateTime(long.Parse(p),DateTimeKind.Local),10=>1.5f,_=>new object()};
 static string Read(Func<string> f){try{return H(f());}catch(Exception e){return "E:"+Error(e);}}
 static string Model(object value,string payload){var r=new XmlRpcResponse(-77,payload);string s=r.IsFault+":"+r.FaultCode+":"+H(r.FaultString);r.Value=value;s+=":"+r.IsFault+":"+r.FaultCode+":"+H(r.FaultString);r.SetFault(42,null);return s+":"+r.IsFault+":"+r.FaultCode+":"+H(r.FaultString);}
 public static void Main(){CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;string line;while((line=Console.ReadLine())!=null){var a=line.Split(' ');int mode=int.Parse(a[0]),shape=int.Parse(a[1]),flags=int.Parse(a[2]),kind=int.Parse(a[3]);string payload=D(a[4]),method=D(a[5]);object atom=Atom(kind,payload),value=shape switch{0=>atom,1=>new ArrayList{atom,null,atom},2=>new OrderedDictionary{{"z",atom},{"a",null},{"last",atom}},_=>new ArrayList{new OrderedDictionary{{"a",atom},{"b",new ArrayList{null,atom}}},atom}};XmlRpcRequest request=(flags&1)!=0?null:new XmlRpcRequest(method,(flags&2)!=0?null:new ArrayList{value});XmlRpcResponse response=(flags&1)!=0?null:new XmlRpcResponse{Value=value,IsFault=(flags&4)!=0};string names=Read(()=>request.MethodNameObject)+":"+Read(()=>request.MethodNameMethod);string error="-",close="-",data;
 using(var stream=new MemoryStream()) {var writer=new XmlTextWriter(stream,new UTF8Encoding());if((flags&16)!=0){writer.Formatting=Formatting.Indented;writer.Indentation=4;}try{if(mode==0)new XmlRpcRequestSerializer().Serialize(writer,request);else if(mode==1)new XmlRpcResponseSerializer().Serialize(writer,response);else new XmlRpcSerializer().SerializeObject(writer,value);writer.Flush();}catch(Exception e){error=Error(e);}try{writer.Close();}catch(Exception e){close=Error(e);}data=Convert.ToHexString(stream.ToArray()).ToLowerInvariant();}
 string pretty="-";try{if(mode==0)pretty=Convert.ToHexString(Encoding.UTF8.GetBytes(request.ToString())).ToLowerInvariant();else if(mode==1)pretty=Convert.ToHexString(Encoding.UTF8.GetBytes(response.ToString())).ToLowerInvariant();}catch(Exception e){pretty="E:"+Error(e);}Console.WriteLine(Model(value,payload)+"|"+names+"|"+error+"|"+close+"|"+data+"|"+pretty);}}
}
